## The only place that drives the AnimationPlayer. It runs in manual mode, so the clip moves only when the
## simulation ticks or an override is set; a frozen run freezes the courier.
func _show() -> void:
	if anim == null:
		return
	visual.visible = sheet != null
	visual.scale.x = facing
	var shown := clip_and_time()
	anim.play(shown[0])
	anim.seek(shown[1], true)

for y in range(-1, 33):
	for x in range(-1, 33):
		if opaque.call(x, y):
			continue
		for part in OUTLINE_PARTS:
			var region: Rect2 = PARTS[part]["region"]
			for d in [Vector2i(1, 0), Vector2i(-1, 0), Vector2i(0, 1), Vector2i(0, -1)]:
				var n: Vector2i = Vector2i(x, y) + d
				if opaque.call(n.x, n.y) and region.has_point(Vector2(n) + Vector2(0.5, 0.5)):
					rings[part].append(Vector2i(x, y))
					break
